// ExtractKnownError 从 err 的错误链中提取一个已定义的业务错误。
// 若 err 链中包含匹配的错误，则返回该错误（转换为 *errors.Error）和 true；否则返回 (nil, false)。
//
// 典型用法：业务逻辑中可以不断 wrap 错误，接口最外层通过该函数提取并返回给前端。
func ExtractKnownError(err error) (*errors.Error, bool) {
	if err == nil {
		return nil, false
	}

	// 优先从 error chain 中寻找 *errors.Error，避免 FromError() 丢失原始 metadata。
	var se *errors.Error
	if errors.As(err, &se) && se != nil {
		if e, ok := matchKnown(se); ok {
			return e, true
		}
	}

	e := errors.FromError(err)
	if e == nil {
		return nil, false
	}
	if e2, ok := matchKnown(e); ok {
		return e2, true
	}
	return nil, false
}

func matchKnown(e *errors.Error) (*errors.Error, bool) {
	if e == nil {
		return nil, false
	}
	if IsPlayerNotFound(e) {
		return e, true
	}
	if IsPlayerAlreadyExists(e) {
		return e, true
	}
	if IsInvalidToken(e) {
		return e, true
	}
	if IsKickedOffline(e) {
		return e, true
	}
	if IsTokenExpired(e) {
		return e, true
	}
	if IsSessionNotFound(e) {
		return e, true
	}
	if IsPlayerNotOnline(e) {
		return e, true
	}
	if IsInvalidParams(e) {
		return e, true
	}
	if IsPasswordWrong(e) {
		return e, true
	}
	if IsServerFrozen(e) {
		return e, true
	}
	if IsClientVersionTooLow(e) {
		return e, true
	}
	if IsAdminOperatorMissing(e) {
		return e, true
	}
	if IsAdminIdempotencyKeyMissing(e) {
		return e, true
	}
	if IsAdminIdempotencyKeyReused(e) {
		return e, true
	}
	if IsAdminOperationInFlight(e) {
		return e, true
	}
	if IsAdminGrantCountExceeded(e) {
		return e, true
	}
	if IsAlreadyInMatch(e) {
		return e, true
	}
	if IsMatchNotFound(e) {
		return e, true
	}
	if IsPartyNotFound(e) {
		return e, true
	}
	if IsPartyFull(e) {
		return e, true
	}
	if IsAlreadyInParty(e) {
		return e, true
	}
	if IsNotPartyLeader(e) {
		return e, true
	}
	if IsNotInParty(e) {
		return e, true
	}
	if IsBattleNotFound(e) {
		return e, true
	}
	if IsBattleFull(e) {
		return e, true
	}
	if IsBattleEnded(e) {
		return e, true
	}
	if IsBattleTicketInvalid(e) {
		return e, true
	}
	if IsBattleTicketExpired(e) {
		return e, true
	}
	if IsInternal(e) {
		return e, true
	}
	return nil, false
}
